Definition cfg_hi_Z (b1 : Z) : Z :=
  Z.shiftr ((2 ^ 57 * (bv_swrap 8 b1 mod 2 ^ 64)) mod 2 ^ 64) 49.

Definition cfg_hi_ok (b1 : Z) : bool := Z.eqb (cfg_hi_Z b1) (256 * (b1 mod 128)).

Lemma cfg_hi_all : forallb cfg_hi_ok (map Z.of_nat (seq 0 256)) = true.
Proof. ltac2:(KReplay.run [|constr:(@Corelib.Init.Logic.eq_refl); constr:(@Corelib.Init.Datatypes.bool); constr:(@Corelib.Init.Datatypes.true); constr:(@Corelib.Init.Logic.eq); constr:(@Stdlib.Lists.List.forallb); constr:(@Corelib.Numbers.BinNums.Z); constr:(@OSSVerify.Proofs.boost_beast.http_request.lib.Ub.MainArith.cfg_hi_ok); constr:(@Corelib.Lists.ListDef.map); constr:(@Corelib.Init.Datatypes.nat); constr:(@Stdlib.ZArith.BinInt.Z.of_nat); constr:(@Corelib.Lists.ListDef.seq); constr:(@Corelib.Init.Datatypes.O); constr:(@Corelib.Init.Datatypes.S)|] Array.empty "#%q###0#'#(#1#+#&#0#-#.#/#*#,#)#2$#/$VGCD#E##############################################################################################################################################################################################################################################################################################################################################################################################################################################################################################################################VHE#XIJFK#WLFM#WNC#Dm$s%O##"). Qed.

Lemma cfg_hi_val : forall b1, 0 <= b1 < 256 -> cfg_hi_Z b1 = 256 * (b1 mod 128).
Proof.
  intros b1 Hb.
  assert (Hin : In b1 (map Z.of_nat (seq 0 256))).
  { apply in_map_iff. exists (Z.to_nat b1). split; [lia|]. apply in_seq. lia. }
  pose proof (proj1 (forallb_forall _ _) cfg_hi_all b1 Hin) as H. unfold cfg_hi_ok in H.
  apply Z.eqb_eq in H. exact H.
Qed.
