Lemma hdr_cfg_eq : forall data, (2 <= length data)%nat ->
  hdr_cfg data = (hdr_b data 0 + 256 * hdr_b data 1) mod 32768.
Proof. intros. reflexivity. Qed.

Lemma hdr_b_range : forall data i, 0 <= hdr_b data i < 256.
Proof.
  intros data i. unfold hdr_b. pose proof (bv_unsigned_in_range 8 (nth i data (Z_to_bv 8 0))) as Hr.
  unfold bv_modulus in Hr. cbn in Hr. lia.
Qed.

Lemma hdr_cfg_range : forall data, 0 <= hdr_cfg data < 32768.
Proof. intros. unfold hdr_cfg. apply Z.mod_pos_bound. lia. Qed.
